#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
F="$GSZ/lib/mailer.js"
TS=$(date +%Y%m%d-%H%M%S); BK="$F.bak-step195-$TS"
echo "==> step195: send email via Brevo HTTPS API (SMTP ports are blocked by the host)"
cp "$F" "$BK"; echo "    backup: $BK"
restore(){ echo "!! restoring"; cp "$BK" "$F" 2>/dev/null||true; }
trap 'restore' ERR
echo "" | base64 -d > "$F"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$F" && echo "    mailer.js ok"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
trap - ERR
echo ""
echo "==> step195 OK  mailer.js now sends via Brevo's HTTPS API (port 443). Set BREVO_API_KEY in .env, keep GSZ_SMTP_FROM, then test."
